INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u08-l01','course-a1-foundations','weather-today-a1','Weather Today','Describe simple weather conditions and understand basic weather words.','A1',36,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u08-l01-q01','a1-u08-l01','multiple_choice','What is the weather like when the sun is shining?','[{"id":"a","text":"sunny"},{"id":"b","text":"snowy"},{"id":"c","text":"windy"}]','a','Sunny describes weather with a lot of sunshine.',1),
('a1-u08-l01-q02','a1-u08-l01','multiple_choice','Which word describes a lot of water falling from the sky?','[{"id":"a","text":"rainy"},{"id":"b","text":"cloudy"},{"id":"c","text":"hot"}]','a','Rainy describes weather with rain.',2),
('a1-u08-l01-q03','a1-u08-l01','multiple_choice','What do you see in the sky on a cloudy day?','[{"id":"a","text":"clouds"},{"id":"b","text":"leaves"},{"id":"c","text":"windows"}]','a','Clouds cover some or all of the sky.',3),
('a1-u08-l01-q04','a1-u08-l01','multiple_choice','Complete: It ___ cold today.','[{"id":"a","text":"is"},{"id":"b","text":"are"},{"id":"c","text":"am"}]','a','Use it is to describe the weather.',4);
