INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u08-l02','course-a1-foundations','seasons-and-months-a1','Seasons and Months','Name the seasons and recognise common months of the year.','A1',37,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u08-l02-q01','a1-u08-l02','multiple_choice','Which season is usually the coldest?','[{"id":"a","text":"winter"},{"id":"b","text":"summer"},{"id":"c","text":"spring"}]','a','Winter is generally the coldest season in many regions.',1),
('a1-u08-l02-q02','a1-u08-l02','multiple_choice','Which season comes after spring?','[{"id":"a","text":"summer"},{"id":"b","text":"autumn"},{"id":"c","text":"winter"}]','a','Summer follows spring in the usual four-season cycle.',2),
('a1-u08-l02-q03','a1-u08-l02','multiple_choice','How many months are there in a year?','[{"id":"a","text":"twelve"},{"id":"b","text":"ten"},{"id":"c","text":"seven"}]','a','There are twelve months in a year.',3),
('a1-u08-l02-q04','a1-u08-l02','multiple_choice','Which month comes after June?','[{"id":"a","text":"July"},{"id":"b","text":"May"},{"id":"c","text":"September"}]','a','July comes after June.',4);
