INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u08-l03','course-a1-foundations','clothes-and-colours-a1','Clothes and Colours','Name everyday clothes and describe their colours.','A1',38,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u08-l03-q01','a1-u08-l03','multiple_choice','Which item do you wear on your feet?','[{"id":"a","text":"shoes"},{"id":"b","text":"gloves"},{"id":"c","text":"hat"}]','a','Shoes are worn on the feet.',1),
('a1-u08-l03-q02','a1-u08-l03','multiple_choice','Which item do you wear around your neck in cold weather?','[{"id":"a","text":"scarf"},{"id":"b","text":"shorts"},{"id":"c","text":"sandals"}]','a','A scarf keeps the neck warm.',2),
('a1-u08-l03-q03','a1-u08-l03','multiple_choice','What colour do you get when you mix blue and yellow paint?','[{"id":"a","text":"green"},{"id":"b","text":"purple"},{"id":"c","text":"orange"}]','a','Blue and yellow paint make green.',3),
('a1-u08-l03-q04','a1-u08-l03','multiple_choice','Complete: She has a ___ dress.','[{"id":"a","text":"red"},{"id":"b","text":"reds"},{"id":"c","text":"redding"}]','a','Use a colour adjective before the noun.',4);
