INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u08-l04','course-a1-foundations','what-are-you-wearing-a1','What Are You Wearing?','Ask and answer simple questions about clothes people are wearing.','A1',39,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u08-l04-q01','a1-u08-l04','multiple_choice','Choose the correct question.','[{"id":"a","text":"What are you wearing?"},{"id":"b","text":"What you are wearing?"},{"id":"c","text":"What is you wearing?"}]','a','Use are with you in the present continuous question.',1),
('a1-u08-l04-q02','a1-u08-l04','multiple_choice','Complete: He is ___ a blue shirt.','[{"id":"a","text":"wearing"},{"id":"b","text":"wear"},{"id":"c","text":"wears"}]','a','Present continuous uses be + verb-ing.',2),
('a1-u08-l04-q03','a1-u08-l04','multiple_choice','Complete: They ___ wearing coats.','[{"id":"a","text":"are"},{"id":"b","text":"is"},{"id":"c","text":"am"}]','a','Use are with the subject they.',3),
('a1-u08-l04-q04','a1-u08-l04','multiple_choice','Which sentence describes something happening now?','[{"id":"a","text":"I am wearing a jacket."},{"id":"b","text":"I wear a jacket every winter."},{"id":"c","text":"I wore a jacket yesterday."}]','a','Present continuous can describe what someone has on now.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u08-l04:v1','a1-u08-l04',1,'What Are You Wearing?','Ask and answer simple questions about clothes people are wearing.','A1',39,'draft',NULL);
