INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u08-l05','course-a1-foundations','weather-and-everyday-plans-a1','Weather and Everyday Plans','Choose suitable clothes and simple activities for different weather.','A1',40,1,'published');
